# Generates IfClasses.h/.cpp and targets_ifs.txt for the IfFunction subclasses from the RTTI table and the exe.
use strict;
chdir "../../.." or die;
my $exe = do { local $/; open my $f, "<:raw", "Exported/SQZ.EXE" or die; <$f> };
sub rva2off { my ($va) = @_; my $pe = unpack('V', substr($exe,0x3c,4)); my ($nsec,$opt) = unpack('x6 v x12 v', substr($exe,$pe,24)); my $base = unpack('V', substr($exe,$pe+24+28,4));
  for my $i (0..$nsec-1) { my ($vs,$va0,$rs,$rp) = unpack('x8 V V V V', substr($exe,$pe+24+$opt+$i*40,40)); my $r = $va-$base; return $rp+$r-$va0 if $r >= $va0 && $r < $va0+$vs; } die }
sub cstr { my ($va) = @_; return unpack('Z*', substr($exe, rva2off($va), 64)); }
sub bytes { my ($va,$n) = @_; return substr($exe, rva2off($va), $n); }
my %fsz; { open my $ff, "<nm/fns_all.txt" or die; while (<$ff>) { $fsz{hex($1)} = $2 if /^([0-9a-f]+) size=(\d+)/ } }
sub sizearg { my ($a) = @_; return "" if exists $fsz{$a}; for my $s (keys %fsz) { return " " . ($s + $fsz{$s} - $a) if $s < $a && $a < $s + $fsz{$s} } return "" }
open R, "<tools/rtti.tsv"; my @cls;
while (<R>) { chomp; my @f = split /\t/; next unless $f[0] =~ /^\.\?AV(\w+Function)\@\@$/; my $cn = $1; next unless ($f[3] // '') =~ /^\.\?AVIf(Function|OnSurfaceTypeFunction)\@\@/; next if $cn =~ /^IfVariable|^IfOn(Face|OrAbove|Surface)/; my @s = map { hex } split /;/, $f[4]; push @cls, [$cn, hex($f[1]), @s]; }
sub sddsize { my ($a) = @_; my $n = $fsz{$a} // 128; my $b = bytes($a, $n + 64);
  for my $i (0..$n-5) { next unless substr($b,$i,1) eq "\xe8"; my $t = $a + $i + 5 + unpack('l', substr($b,$i+1,4)); return $t + 8 - $a if $t > $a + $n - 8 && $t < $a + $n + 40; }
  return $n; }
my $q = '^' . chr(92) . '?'; my $bs = chr(92);
my (@h, @c, @t);
for my $c (@cls) {
  my ($n, $vt, $sdd, $exec, $create, $print, $name, $parse, $dump, $test, $make) = @$c;
  (my $short = $n) =~ s/Function$//;
  next if grep { $_ == 0x48e4d0 } ($name, $parse, $dump, $test, $make);
  my $nb = bytes($name, 6); my $str = (unpack('C', $nb) == 0xb8) ? cstr(unpack('V', substr($nb,1,4))) : undef;
  my $pb = bytes($parse, 8); my $parseOk = ($pb eq "\xb8\x01\x00\x00\x00\xc2\x04\x00");
  my $db = bytes($dump, 1); my $dumpOk = ($db eq "\xc3");
  my $tb = bytes($test, 8); my ($testBody) = ($tb eq "\xb8\x01\x00\x00\x00\xc2\x08\x00") ? ('return 1;') : ($tb =~ /^\x33\xc0\xc2\x08\x00/) ? ('return 0;') : (undef);
  push @h, "class $n : public IfFunction {\npublic:\n" . (sddsize($sdd) == 104 ? "    ~$n() {}\n" : "") . "    virtual const char *Name();\n    virtual int Parse(ArgList *list);\n    virtual void Dump();\n    virtual int Test(ScriptCall *args, int extra);\n    virtual IfFunction *Make();\n};\n";
  my $body = '';
  if (defined $str) { $body .= "const char *$n\::Name() { return \"$str\"; }\n"; push @t, $q . "Name\@$n  " . sprintf("%x", $name) . " ${short}_name\n"; }
  if ($parseOk) { $body .= "int $n\::Parse(ArgList *list) { return 1; }\n"; push @t, $q . "Parse\@$n  " . sprintf("%x", $parse) . " ${short}_parse\n"; }
  if ($dumpOk) { $body .= "void $n\::Dump() {}\n"; push @t, $q . "Dump\@$n  " . sprintf("%x", $dump) . " ${short}_dump\n"; }
  if (defined $testBody) { $body .= "int $n\::Test(ScriptCall *args, int extra) { $testBody }\n"; push @t, $q . "Test\@$n  " . sprintf("%x", $test) . " ${short}_test\n"; }
  $body .= "IfFunction *$n\::Make() { return new $n; }\n"; push @t, $q . "Make\@$n  " . sprintf("%x", $make) . " ${short}_make" . sizearg($make) . "\n";
  push @t, $q . $bs . "?_G$n  " . sprintf("%x", $sdd) . " ${short}_sdd " . sddsize($sdd) . "\n";
  push @c, $body;
}
open H, ">Repo/bm/FunctionIf/IfClasses.h"; print H "// The IfFunction subclasses (generated by gen.pl from the RTTI table).\n#pragma once\n#include \"FunctionIf/FunctionIf.h\"\n\n", join("\n", @h); close H;
open C, ">Repo/bm/FunctionIf/IfClasses.cpp"; print C "// Small slots of the IfFunction subclasses (generated by gen.pl).\n#include \"FunctionIf/IfClasses.h\"\n\n", join("\n", @c); close C;
open T, ">Repo/bm/FunctionIf/targets_ifs.txt"; print T @t; close T;
print scalar(@cls), " classes\n";
